<?php
require_once __DIR__ . '/../_common.php';api_require_role('admin');
try{
 $m=api_allow_methods(['GET','PUT']);
 if($m==='GET'){$sql='SELECT p.id_pengajuan,p.id_akun,p.id_user,p.field_diajukan,p.nilai_lama,p.nilai_baru,p.alasan,p.status_pengajuan,p.tanggal_pengajuan,p.tanggal_diproses,p.diproses_oleh,a.nama AS nama_fo,u.nama AS nama_user FROM pengajuan_perubahan p LEFT JOIN akun a ON a.id_akun=p.id_akun LEFT JOIN users u ON u.id_user=p.id_user WHERE 1=1';$types='';$vals=[];if(!empty($_GET['status_pengajuan'])){$sql.=' AND p.status_pengajuan=?';$types.='s';$vals[]=api_string($_GET['status_pengajuan'],'status_pengajuan',20);}if(!empty($_GET['id_akun'])){$sql.=' AND p.id_akun=?';$types.='i';$vals[]=api_int($_GET['id_akun'],'id_akun');}$sql.=' ORDER BY p.tanggal_pengajuan DESC,p.id_pengajuan DESC';$st=$conn->prepare($sql);if($types)api_bind($st,$types,$vals);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();api_reply(200,true,'Daftar pengajuan berhasil diambil.',$rows);}
 $b=api_body();$id=api_int($b['id_pengajuan']??null,'id_pengajuan');$decision=$b['status_pengajuan']??($b['keputusan']??'');if(!in_array($decision,['disetujui','ditolak'],true))throw new InvalidArgumentException('status_pengajuan harus disetujui atau ditolak.');
 $conn->begin_transaction();try{$st=$conn->prepare('SELECT id_pengajuan,id_akun,field_diajukan,nilai_baru,status_pengajuan FROM pengajuan_perubahan WHERE id_pengajuan=? FOR UPDATE');$st->bind_param('i',$id);$st->execute();$row=api_one($st);$st->close();if(!$row)throw new OutOfBoundsException('Pengajuan tidak ditemukan.');if($row['status_pengajuan']!=='menunggu')throw new LogicException('Pengajuan sudah diproses.');
  if($decision==='disetujui'){$allowed=['nama'=>'nama','no_telp'=>'no_telp','alamat'=>'alamat','gender'=>'gender','jam_mulai'=>'jam_mulai','jam_selesai'=>'jam_selesai'];$field=$row['field_diajukan'];if(!isset($allowed[$field])||$row['id_akun']===null)throw new DomainException('Pengajuan tidak menunjuk field akun yang dapat diperbarui.');$value=$row['nilai_baru'];if($field==='gender'&&!in_array($value,['L','P'],true))throw new DomainException('Nilai gender pengajuan tidak valid.');$update=$conn->prepare('UPDATE akun SET '.$allowed[$field].'=? WHERE id_akun=?');$idA=(int)$row['id_akun'];$update->bind_param('si',$value,$idA);$update->execute();if($update->affected_rows===0){$check=$conn->prepare('SELECT id_akun FROM akun WHERE id_akun=?');$check->bind_param('i',$idA);$check->execute();$exists=api_one($check);$check->close();if(!$exists)throw new OutOfBoundsException('Akun FO terkait tidak ditemukan.');}$update->close();}
  $by=(int)$_SESSION['id_akun'];$st=$conn->prepare('UPDATE pengajuan_perubahan SET status_pengajuan=?,status=?,tanggal_diproses=NOW(),diproses_oleh=? WHERE id_pengajuan=?');$st->bind_param('ssii',$decision,$decision,$by,$id);$st->execute();$st->close();$conn->commit();
 }catch(Throwable $e){$conn->rollback();throw $e;}api_reply(200,true,'Pengajuan berhasil diproses.',['id_pengajuan'=>$id,'status_pengajuan'=>$decision]);
}catch(Throwable $e){api_db_error($e);}